<script lang="ts">
    import { onMount, onDestroy } from 'svelte'
    import { open } from '@tauri-apps/plugin-shell'
    import { mailInOutlook, setMailInOutlook } from '@/lib/outlook'
    import { outlook, mailUnreadOnly, outlookApi, editDraft, refreshMail, selectMail, prepareMail, sendMail, saveMailDraft, cancelMailSend, replyToMail, disconnectMail, setMailStatus, setMailCode, mailError, mailAction } from '@/lib/outlook'
    let clientId = '', query = '', showSetup = false, localSupported = false
    let polling: ReturnType<typeof setTimeout> | undefined, disposed = false, loginGeneration = 0
    const run = (action: () => Promise<unknown>) => action().catch(mailError)
    $: visible = $outlook.messages.map((mail, index) => ({ mail, number: index + 1 })).filter(({ mail }) => (!$mailUnreadOnly || !mail.isRead) && `${mail.subject} ${mail.from?.emailAddress?.name ?? ''} ${mail.from?.emailAddress?.address ?? ''} ${mail.bodyPreview ?? ''}`.toLowerCase().includes(query.toLowerCase()))
    async function connect() {
        const generation = ++loginGeneration
        await mailAction(async () => {
            const result = await outlookApi<{ code: string; interval: number }>('connect', { clientId })
            localStorage.setItem('jarvis-outlook-client-id', clientId.trim())
            setMailCode(result.code)
            clearTimeout(polling)
            polling = setTimeout(() => poll(generation), result.interval * 1000)
        })
    }
    async function connectLocal() {
        await mailAction(async () => {
            setMailStatus(await outlookApi('connect_local'))
        })
        await refreshMail()
    }
    async function poll(generation: number) {
        if (disposed || generation !== loginGeneration) return
        try {
            const status = await outlookApi<{ connected: boolean; pending: boolean; account?: { name: string; email: string } }>('poll')
            if (disposed || generation !== loginGeneration) return
            setMailStatus(status)
            if (status.connected) { await run(refreshMail); return }
            if (status.pending) polling = setTimeout(() => poll(generation), 5000)
            else setMailCode('')
        } catch (error) { if (!disposed && generation === loginGeneration) { setMailCode(''); mailError(error) } }
    }
    async function disconnect() { loginGeneration++; clearTimeout(polling); await disconnectMail() }
    onMount(() => {
        clientId = localStorage.getItem('jarvis-outlook-client-id') ?? ''
        run(async () => {
            const status = await outlookApi<{ connected: boolean; pending: boolean; localSupported?: boolean }>('status')
            localSupported = status.localSupported === true
            if (!localSupported && $mailInOutlook) setMailInOutlook(false)
            setMailStatus(status)
            if (status.connected && !$outlook.messages.length) await refreshMail()
            else if (status.pending && $outlook.code) polling = setTimeout(() => poll(loginGeneration), 5000)
        })
    })
    onDestroy(() => { disposed = true; loginGeneration++; clearTimeout(polling) })
    const formatDate = (value: string) => new Date(value).toLocaleString('ru-RU', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' })
</script>

<section class="mail-center" aria-label="Почта Outlook">
    <header><div><p class="eyebrow">JARVIS / OUTLOOK</p><h2>Письма. Без суеты.</h2><p class="muted">{localSupported ? 'Классический Outlook / Kerio и Microsoft 365 — в одном разделе.' : 'Microsoft 365 / Outlook.com. Подключение Kerio доступно только в Windows.'}</p></div><span class="connection" class:online={$outlook.connected}><i></i>{$outlook.connected ? 'Подключено' : 'Не подключено'}</span></header>
    {#if $outlook.error}<div role="alert" class="banner error">{$outlook.error}</div>{/if}
    {#if $outlook.notice}<div role="status" class="banner">{$outlook.notice}</div>{/if}
    {#if localSupported}<div class="panel mode-choice">
        <h3>Где управлять почтой голосом?</h3>
        <div class="compose-actions"><button aria-pressed={!$mailInOutlook} class:primary={!$mailInOutlook} disabled={$outlook.busy} on:click={() => setMailInOutlook(false)}>В JARVIS</button><button aria-pressed={$mailInOutlook} class:primary={$mailInOutlook} disabled={$outlook.busy || ($outlook.connected && $outlook.provider !== 'local')} on:click={() => setMailInOutlook(true)}>В окне Outlook</button></div>
        <p class="muted">Внешний режим работает с классическим Outlook / Kerio. JARVIS должен оставаться запущенным для распознавания голоса. Почтовый раздел приложения остаётся доступен.</p>
        <details class="setup kerio-guide"><summary>Запасной способ настройки профиля Outlook</summary><ol><li>Нажмите Win+R, введите <code>control mlcfg32.cpl</code> и нажмите Enter. Откроется окно «Почта» классического Outlook.</li><li>Нажмите «Показать профили → Добавить». Назовите профиль, например JARVIS-Test. Выберите ручную настройку и Kerio Connect; Connector должен соответствовать разрядности Outlook.</li><li>В Kerio укажите сервер, адрес ящика и пароль. Во вкладке «Сведения о сервере» включите SSL и правильный HTTPS-порт. Только для нашей локальной лаборатории: сервер <code>127.0.0.1</code>, порт <code>14443</code>. Для рабочей почты используйте параметры администратора.</li><li>Нажмите «Обнаружить», проверьте адрес, сохраните настройки. Выберите нужный профиль при запуске классического Outlook, дождитесь синхронизации и нажмите в JARVIS «Подключить открытый Outlook».</li><li>Если команда не открыла окно: «Панель управления → Почта (Microsoft Outlook)». Другой вариант для установленного Office — <code>control "C:\Program Files\Microsoft Office\root\Office16\MLCFG32.CPL"</code>; у 32-битного Office путь может начинаться с Program Files (x86). Новый Outlook с Kerio Connector не работает.</li></ol></details>
        {#if $mailInOutlook}<p class="muted">«Открой почту» · «Обнови письма» · «Напиши письмо» · «Отправь письмо». Перед отправкой открывается отдельный черновик Outlook. Правки после проверки блокируют отправку; отмена оставляет черновик в Outlook.</p>{/if}
    </div>{/if}
    {#if !$outlook.connected}
        <div class="provider-options">
        {#if localSupported}<section class="panel connect local-provider" aria-labelledby="local-provider-title">
            <div class="provider-heading"><div class="provider-icon" aria-hidden="true">✉</div><span class="provider-badge">Локальное подключение</span></div>
            <p class="eyebrow">НА ЭТОМ КОМПЬЮТЕРЕ</p>
            <h3 id="local-provider-title">Классический Outlook / Kerio</h3>
            <p>Подключите почту из уже открытого классического Outlook. Учётные данные остаются в Outlook — Client ID не нужен.</p>
            <ul class="provider-details"><li>Один аккаунт в открытом профиле</li><li>Чтение писем и сохранение черновиков проверены на локальном Kerio</li><li>Отправка — только после вашего подтверждения; сквозная доставка из JARVIS ещё не проверена</li></ul>
            <button class="primary" on:click={() => run(connectLocal)} disabled={$outlook.busy || !!$outlook.code}>Подключить открытый Outlook</button>
            <small class="provider-footnote">Для текущего теста оставьте Outlook открытым с ящиком angel@jarvis.test.</small>
            <details class="setup kerio-guide"><summary>Как подключить Kerio — пошагово</summary><ol><li>Установите классический Outlook и Kerio Outlook Connector той же разрядности. Новый Outlook для этого режима не подходит.</li><li>Откройте «Панель управления → Почта → Показать профили → Добавить». Создайте отдельный профиль, затем выберите ручную настройку и службу Kerio Connect.</li><li>Укажите сервер, полный адрес ящика и его пароль. Для рабочей почты параметры выдаёт ваш администратор — не используйте адрес нашей лаборатории.</li><li>В «Сведения о сервере» включите SSL и укажите HTTPS-порт сервера. Для нашего локального теста: <code>127.0.0.1</code>, порт <code>14443</code>, ящик <code>angel@jarvis.test</code>. Исключение проверки доверенного сертификата допустимо только для этой локальной лаборатории, не для корпоративного сервера.</li><li>Нажмите «Обнаружить», проверьте имя и адрес → ОК. Запустите классический Outlook с выбранным профилем и дождитесь синхронизации.</li><li>Оставьте один аккаунт в открытом профиле и нажмите «Подключить открытый Outlook» здесь. Выберите «В JARVIS» или «В окне Outlook». Пароль JARVIS не нужен.</li></ol><p>При смене профиля подключитесь заново. Если Outlook показывает запрос безопасности, проверьте его вручную; JARVIS не отключает защиту. Не отправляйте реальные письма, пока не проверите тестовый ящик.</p></details>
        </section>{/if}
        <section class="panel connect cloud-provider" aria-labelledby="cloud-provider-title">
            <div class="provider-heading"><div class="provider-icon" aria-hidden="true">☁</div><span class="provider-badge experimental">Экспериментально</span></div>
            <p class="eyebrow">ЧЕРЕЗ MICROSOFT GRAPH</p>
            <h3 id="cloud-provider-title">Microsoft 365 / Outlook.com</h3>
            <div class="provider-warning" role="note"><strong>Реализовано · не проверено на реальном аккаунте</strong><p>Вход, чтение и отправка реализованы, но пока не прошли сквозное тестирование с Microsoft 365 / Outlook.com. Возможны ошибки; подключение или отдельные функции могут не работать.</p></div>
            <p>Вход проходит на сайте Microsoft. JARVIS не просит пароль почты. Доступ действует до закрытия приложения; токены остаются только в памяти.</p>
            <label for="outlook-client-id">Application (client) ID</label><div class="connect-row"><input id="outlook-client-id" bind:value={clientId} placeholder="xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx" autocomplete="off" spellcheck="false" disabled={$outlook.busy || !!$outlook.code}/><button class="primary" on:click={() => run(connect)} disabled={$outlook.busy || !clientId.trim() || !!$outlook.code}>{$outlook.busy ? 'Подключаю…' : 'Получить код входа'}</button></div>
            {#if $outlook.code}<div class="device"><span>Откройте сайт Microsoft и введите код</span><strong>{$outlook.code}</strong><a href="https://microsoft.com/devicelogin" on:click|preventDefault={() => run(() => open('https://microsoft.com/devicelogin'))} target="_blank" rel="noopener noreferrer">Войти в Microsoft ↗</a><small>Ожидаю подтверждения входа…</small><button on:click={() => run(disconnect)}>Отменить вход</button></div>{/if}
            <button class="text-button" aria-expanded={showSetup} on:click={() => showSetup = !showSetup}>{showSetup ? 'Скрыть инструкцию' : 'У меня нет Client ID — как его получить?'}</button>
            {#if showSetup}<div class="setup"><h4>Регистрация — один раз</h4><ol><li>Откройте <a href="https://entra.microsoft.com/" on:click|preventDefault={() => run(() => open('https://entra.microsoft.com/'))} target="_blank" rel="noopener noreferrer">Microsoft Entra ↗</a>, затем «App registrations» → «New registration».</li><li>Укажите название «JARVIS Outlook». Выберите аккаунты любых организаций <em>и личные Microsoft accounts</em>. Redirect URI для этого способа входа не нужен.</li><li>После регистрации скопируйте <em>Application (client) ID</em> и вставьте выше.</li><li>В «Authentication» включите <em>Allow public client flows</em> и сохраните.</li><li>В «API permissions» → Microsoft Graph → Delegated permissions добавьте <code>User.Read</code>, <code>Mail.ReadWrite</code>, <code>Mail.Send</code> и <code>offline_access</code>.</li><li>Нажмите «Получить код входа», войдите на сайте Microsoft и подтвердите разрешения.</li></ol><p>Client secret не нужен — не создавайте и не присылайте его. Для рабочей почты администратор может запретить этот вход или потребовать согласие. Если регистрация недоступна, потребуется помощь администратора Microsoft Entra.</p></div>{/if}
        </section>
        </div>
    {:else}
        <div class="account"><div><strong>{$outlook.account.name || 'Microsoft Outlook'}</strong><small>{$outlook.account.email}</small></div><button on:click={() => run(disconnect)} disabled={$outlook.busy}>Отключить аккаунт</button></div>
        <div class="mail-grid">
            <div class="panel inbox"><div class="panel-head"><h3>Входящие <small>{$outlook.messages.length}</small></h3><button on:click={() => run(refreshMail)} disabled={$outlook.busy} aria-label="Обновить входящие">↻ Обновить</button></div><input aria-label="Поиск среди загруженных писем" placeholder="Поиск среди 50 последних писем" bind:value={query}/><label class="toggle"><input type="checkbox" bind:checked={$mailUnreadOnly}/> Только непрочитанные</label><div class="messages">{#each visible as { mail, number } (mail.id)}<button class="message" class:selected={$outlook.selected?.id === mail.id} class:unread={!mail.isRead} disabled={$outlook.busy} on:click={() => run(() => selectMail(mail.id))}><span class="message-number">{number}</span><span class="message-copy"><span class="sender">{mail.from?.emailAddress?.name || mail.from?.emailAddress?.address || 'Без отправителя'}</span><strong>{mail.subject || 'Без темы'}</strong><span class="preview">{mail.bodyPreview || ''}</span><time>{formatDate(mail.receivedDateTime)}</time></span>{#if !mail.isRead}<span class="unread-dot" aria-label="Непрочитанное"></span>{/if}</button>{:else}<p class="empty">{$outlook.busy ? 'Загружаю письма…' : 'Подходящих писем нет.'}</p>{/each}</div><small class="muted">Последние 50 входящих. {$outlook.hasMore ? 'Другие письма доступны в Outlook.' : ''} Открытие не меняет отметку прочтения.</small></div>
            <div class="right-column"><article class="panel reader" aria-label="Просмотр письма">{#if $outlook.selected}<p class="eyebrow">ПИСЬМО</p><h3>{$outlook.selected.subject || 'Без темы'}</h3><p class="sender-detail">{$outlook.selected.from?.emailAddress?.name}<br/>{$outlook.selected.from?.emailAddress?.address}</p><div class="mail-body">{$outlook.selected.body?.content || $outlook.selected.bodyPreview || 'Текст отсутствует.'}</div><button on:click={() => { try { replyToMail() } catch (error) { mailError(error) } }} disabled={$outlook.busy}>Написать отправителю ↗</button><small class="muted">Новое письмо с темой Re:, без сохранения цепочки переписки.</small>{:else}<div class="empty reader-empty"><span aria-hidden="true">✉</span><h3>Выберите письмо</h3><p>Или скажите: «Джарвис, открой второе письмо».</p></div>{/if}</article>
            <form class="panel compose" aria-label="Новое письмо" on:submit|preventDefault={() => run(prepareMail)}><div class="panel-head"><h3>Новое письмо</h3><span class="eyebrow">ЧЕРНОВИК</span></div><label for="mail-to">Кому</label><input id="mail-to" type="text" required value={$outlook.draft.to} on:input={(event) => editDraft({ to: event.currentTarget.value })} disabled={$outlook.busy} placeholder="test@jarvis.test; другой@домен.ru"/><label for="mail-subject">Тема</label><input id="mail-subject" required maxlength="250" value={$outlook.draft.subject} on:input={(event) => editDraft({ subject: event.currentTarget.value })} disabled={$outlook.busy}/><label for="mail-body">Текст письма</label><textarea id="mail-body" required maxlength="100000" rows="7" value={$outlook.draft.body} on:input={(event) => editDraft({ body: event.currentTarget.value })} disabled={$outlook.busy} placeholder="Напишите или продиктуйте текст…"></textarea><div class="compose-actions"><button type="button" disabled={$outlook.busy} on:click={() => run(saveMailDraft)}>Сохранить в Outlook</button><button class="primary" disabled={$outlook.busy || !!$outlook.ticket}>Проверить и отправить →</button></div>{#if $outlook.ticket}<div class="confirmation" role="region" aria-label="Подтверждение отправки"><h4>Отправить именно это письмо?</h4><p>Получатели (видимы всем): <strong>{$outlook.draft.to}</strong><br/>Тема: {$outlook.draft.subject}</p><p class="confirm-body">{$outlook.draft.body}</p><div class="compose-actions"><button type="button" on:click={() => run(cancelMailSend)} disabled={$outlook.busy}>Отмена</button><button type="button" class="primary" on:click={() => run(sendMail)} disabled={$outlook.busy}>Да, отправить</button></div></div>{/if}<small class="muted">Текст писем не передаётся в DeepSeek или Ollama автоматически. Несохранённый черновик хранится только до закрытия JARVIS.</small></form></div>
        </div>
    {/if}
    <footer>Голосом: «Открой почту» · «Обнови письма» · «Открой второе письмо» · «Напиши письмо» · «Отправь письмо» · «Отмена»</footer>
</section>

<style>
    .provider-options{display:grid;gap:20px;width:100%;max-width:860px}
    .provider-options .connect{max-width:none;min-width:0;padding:26px}
    .local-provider{border-top:3px solid var(--mail-accent)}
    .cloud-provider{border-top:3px solid #d4b47a;background:linear-gradient(140deg,#172a2d,#111e23)}
    .provider-heading{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:20px}
    .provider-icon{width:46px;height:46px;display:grid;place-items:center;border-radius:14px;background:#53eee510;color:var(--mail-accent);font-size:24px}
    .cloud-provider .provider-icon{background:#d4b47a12;color:#e7c78e}
    .provider-badge{font-size:10px;line-height:1.5;font-weight:700;letter-spacing:.3px;padding:7px 11px;border:1px solid #53eee533;border-radius:30px;color:#9ceee8;background:#53eee508}
    .provider-badge.experimental{border-color:#d4b47a44;color:#e7c78e;background:#d4b47a0c}
    .cloud-provider>.eyebrow{color:#d4b47a}
    .provider-details{padding-left:18px;margin:18px 0 22px;color:var(--mail-muted);font-size:12px;line-height:1.8}
    .provider-details li{padding:4px 0}.provider-details li::marker{color:var(--mail-accent)}
    .provider-footnote{display:block;margin-top:13px}
    .provider-warning{border:1px solid #d4b47a33;border-radius:14px;padding:15px 17px;margin:18px 0;background:#d4b47a08}
    .provider-warning strong{color:#edd2a3;font-size:12px;line-height:1.7;display:block}
    .connect .provider-warning p{margin:7px 0 0;font-size:12px;line-height:1.8;color:#b9bdba}
    @media(max-width:600px){.provider-options .connect{padding:19px}.provider-heading{gap:8px}.provider-badge{font-size:9px}}
    .mail-center{--mail-accent:#53eee5;--mail-border:#26464c;--mail-muted:#8fb0bb;color:#e8f5f7;font-family:'Manrope Variable',sans-serif;display:grid;gap:18px}header{display:flex;justify-content:space-between;gap:20px;align-items:center}h2{font-size:30px;letter-spacing:-1px;margin:4px 0 8px}h3{font-size:18px;margin:0 0 12px}h4{margin:0 0 10px}.eyebrow{color:var(--mail-accent);font-size:10px;font-weight:800;letter-spacing:1.6px}.muted,small{color:var(--mail-muted);font-size:11px;line-height:1.7}.connection{display:flex;align-items:center;gap:8px;border:1px solid var(--mail-border);border-radius:30px;padding:11px 15px;font-size:11px;white-space:nowrap}.connection i{width:6px;height:6px;border-radius:50%;background:#79939a}.connection.online i{background:var(--mail-accent);box-shadow:0 0 10px #53eee544}.panel{border:1px solid var(--mail-border);border-radius:20px;padding:22px;background:linear-gradient(140deg,#122a30,#0b1c21)}.connect{max-width:860px}.connect p{color:var(--mail-muted);font-size:13px;line-height:1.8}.mail-icon{font-size:28px;width:60px;height:60px;display:grid;place-items:center;background:#53eee514;border-radius:18px;color:var(--mail-accent);margin-bottom:16px}label{display:block;font-size:12px;color:#afcbd3;margin:12px 0 7px}input,textarea{box-sizing:border-box;width:100%;background:#081b20;border:1px solid var(--mail-border);border-radius:12px;padding:12px 14px;color:#e8f5f7;font:inherit;font-size:12px;outline:none}input:focus,textarea:focus{border-color:var(--mail-accent);box-shadow:0 0 0 3px #53eee512}textarea{resize:vertical;min-height:120px}button,a{transition:background .18s,border-color .18s;color:inherit}button{border:1px solid var(--mail-border);background:#142e34;padding:10px 14px;border-radius:12px;font:inherit;font-size:11px;cursor:pointer}button:hover:not(:disabled){border-color:var(--mail-accent);background:#1c3c42}button:focus-visible,a:focus-visible{outline:2px solid var(--mail-accent);outline-offset:3px}button:disabled{opacity:.5;cur